                                { "@type": "Question", "name": "Is the Yi Peng lantern release free?", "acceptedAnswer": { "@type": "Answer", "text": "The city festival — parades, candlelit temples and krathong floating — is free. The famous mass synchronised lantern releases are ticketed events outside the city, roughly ฿3,000–12,000+ per person, selling out months ahead." } },
                                { "@type": "Question", "name": "Can I release a lantern anywhere in Chiang Mai?", "acceptedAnswer": { "@type": "Answer", "text": "No. Releases are restricted to approved zones and time windows because Chiang Mai's airport sits beside the city and lanterns are an aviation hazard. Floating a krathong is unrestricted." } },
                                { "@type": "Question", "name": "Will my flight be affected by the lantern festival?", "acceptedAnswer": { "@type": "Answer", "text": "Possibly. Airlines routinely cancel, delay and reroute Chiang Mai flights around the festival nights. Monitor your flight status closely and build in a buffer day." } }
