                                { "@type": "Question", "name": "Why do so many Chiang Mai camps have similar names?", "acceptedAnswer": { "@type": "Answer", "text": "One pioneering no-riding sanctuary built a strong reputation and dozens of camps adopted near-identical naming. Quality ranges from excellent to riding camps that changed their signage — verify the operation, not the name." } },
                                { "@type": "Question", "name": "How much does a Chiang Mai elephant sanctuary cost?", "acceptedAnswer": { "@type": "Answer", "text": "About ฿1,000–2,500 ($30–70) for a half-day including transfer and a meal. Treat very cheap options with suspicion — an adult elephant eats 150–200 kg a day." } }
